    outside=[[False]*W for _ in range(H)]
    q=deque()
    for i in range(H):
        for j in (0,W-1):
            if g[i][j]==0 and not outside[i][j]: outside[i][j]=True;q.append((i,j))
    for j in range(W):
        for i in (0,H-1):
            if g[i][j]==0 and not outside[i][j]: outside[i][j]=True;q.append((i,j))
    while q:
        i,j=q.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<H and 0<=b<W and g[a][b]==0 and not outside[a][b]:
                outside[a][b]=True;q.append((a,b))
    out=[row[:] for row in g]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==0 and not outside[i][j] and not seen[i][j]:
                comp=[];qq=deque([(i,j)]);seen[i][j]=True
                while qq:
                    a,b=qq.popleft();comp.append((a,b))
                    for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
