lib='''"""Shared grid helpers for ARC tasks."""

from collections import deque

def outside_mask(grid):
    """Boolean mask of background (0) cells connected to the grid border."""
    H, W = len(grid), len(grid[0])
    out = [[False]*W for _ in range(H)]
    q = deque()
    for i in range(H):
        for j in (0, W-1):
            if grid[i][j] == 0 and not out[i][j]:
                out[i][j] = True; q.append((i, j))
    for j in range(W):
        for i in (0, H-1):
            if grid[i][j] == 0 and not out[i][j]:
                out[i][j] = True; q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            a, b = i+di, j+dj
            if 0 <= a < H and 0 <= b < W and grid[a][b] == 0 and not out[a][b]:
                out[a][b] = True; q.append((a, b))
    return out

def enclosed_components(grid):
    """List of connected components of 0-cells not connected to the border, each as a list of (i, j)."""
    out = outside_mask(grid)
    H, W = len(grid), len(grid[0])
    seen = [[False]*W for _ in range(H)]
    comps = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 0 and not out[i][j] and not seen[i][j]:
                comp = []; qq = deque([(i, j)]); seen[i][j] = True
                while qq:
                    a, b = qq.popleft(); comp.append((a, b))
                    for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                        x, y = a+di, b+dj
                        if 0 <= x < H and 0 <= y < W and grid[x][y] == 0 and not out[x][y] and not seen[x][y]:
                            seen[x][y] = True; qq.append((x, y))
                comps.append(comp)
    return comps

def bbox_side(comp):
    """Side length of the square box (interior span + 2 border cells) around a component."""
    is_ = [c[0] for c in comp]; js = [c[1] for c in comp]
    return max(max(is_)-min(is_), max(js)-min(js)) + 1 + 2

def fill_enclosed(grid, color_fn):
    """Fill each enclosed 0-region with color_fn(side) where side is its enclosing box's side length."""
    g = [row[:] for row in grid]
    for comp in enclosed_components(grid):
        c = color_fn(bbox_side(comp))
        for a, b in comp:
            g[a][b] = c
    return g
